//! Generated by Codex. Failed borrowed transactions cannot commit until rollback.
use super::*;
use crate::database::db_conn::DBConnSync;
use std::sync::atomic::{AtomicUsize, Ordering};

#[derive(Default)]
struct Connection {
    commits: AtomicUsize,
    rollbacks: AtomicUsize,
}
impl DBConnSync for Connection {
    fn exec_silent(&self, _: &str) -> RS<()> {
        Ok(())
    }
    fn begin_tx(&self) -> RS<OID> {
        Ok(1)
    }
    fn rollback_tx(&self) -> RS<()> {
        self.rollbacks.fetch_add(1, Ordering::SeqCst);
        Ok(())
    }
    fn commit_tx(&self) -> RS<()> {
        self.commits.fetch_add(1, Ordering::SeqCst);
        Ok(())
    }
    fn query(
        &self,
        _: &dyn SQLStmt,
        _: &dyn SQLParams,
    ) -> RS<(Arc<dyn ResultSet>, Arc<TupleFieldDesc>)> {
        Err(mudu_error!(ErrorCode::NotImplemented))
    }
    fn command(&self, _: &dyn SQLStmt, _: &dyn SQLParams) -> RS<u64> {
        Ok(1)
    }
    fn batch(&self, _: &dyn SQLStmt, _: &dyn SQLParams) -> RS<u64> {
        Ok(1)
    }
}

#[test]
fn failed_borrowed_transaction_requires_rollback() -> RS<()> {
    let connection = Arc::new(Connection::default());
    let id = mudu_sys::random::uuid_v4().as_u128();
    let context = Context::create(id, DBConn::Sync(connection.clone()))?;
    context.mark_failed();
    assert!(context.command(&"UPDATE t SET x = 1", &()).is_err());
    assert!(Context::commit(id).is_err());
    assert_eq!(connection.commits.load(Ordering::SeqCst), 0);
    Context::rollback(id)?;
    context.ensure_usable()?;
    assert_eq!(connection.rollbacks.load(Ordering::SeqCst), 1);
    Context::remove(id);
    Ok(())
}
